////////////////////////////////////////////////////////////////////////////////
// 
//  "cpow_afrid()"
//
//  created by Colling Patrik (cyperus) in 2025
//
//  - Test complex power function returning angle, fraction and index.
//
////////////////////////////////////////////////////////////////////////////////

vec4 afrid( in float a, in float p )
{
    // p in { .5, 1., 2., 3., .. }
    p = abs(p); 
    //p = floor(p);

    // global angle
    a *= p; // (for periodic functions, cos sin tan)

    // normalized global angle
    float an = a /PI2;

    // index
    float a_id = floor(an + 0.5);

    // index restrict range
    float a_id_b = floor(p*.5);
    a_id = clamp(a_id, -a_id_b, +a_id_b);

    // fractional local angle
    float a_fr = (an - a_id); // normalized
    a_fr *= PI2;

    // index correction at branchcut
    float a_idc = a_id;
    float sig_even = sign(0.5 - fract( ( p + 0.5 ) *.5) );
    if (  (sig_even == 1.)   // if  is even power
       && (a_id == a_id_b) ) // and is equal largest index bound
    {
        a_idc *= -1.;        // make index negative
    }
    a_idc = (a_idc + a_id_b);

    // angle: global, fract, id, id_corr
    return vec4(a, a_fr, a_id, a_idc);
}

vec2 cpow_afrid( in vec2 z, in float p, out float r, out vec4 av )
{
    av = afrid( atan(z.y ,z.x), p);
    r = length(z);
    return z = pow(r, p) * vec2(cos(av.x), sin(av.x));
}

vec3 color( in float r, in float p, in vec4 av )
{
    vec3 hsv = 
    r>1. ? vec3((av.y + PI2 * av.z)/ (p * PI2), 1., 1.) // global : continuous hue
         : r>.5 ? r>.9 ?  vec3(av.x/ (p * PI2), 1., 1.) // global : continuous hue
                       :  vec3(av.y/ PI2, 1., 1.)       // fract  : continuous periodic hue
                : r>.2 ?  vec3(av.z/p, 1.,              // id     : discrete hue
                               av.y >= 0. ? 1. : 0.5 )  // signum : discrete gray overlay
                       :  vec3(1., 0., av.w/p);         // id_cut : discrete gray
    return hsv2rgb(hsv.x, hsv.y, hsv.z);
}

void mainImage( out vec4 O, in vec2 U )  
{
    vec3 R = iResolution;
    vec2 z = (2.*U-R.xy)/min(R.x, R.y);

    // power: p in{0.5, 1., 2., 3., ...}
    float p = floor(exp(iTime/4.));
    p = (p <= 1.) ? 0.5 : p - 1.;

    float r = 0.;
    vec4 av = vec4(0.);
    z = cpow_afrid(z, p, r, av);

    O = vec4(rgb2srgb( color(r, p, av) ) ,1.);
}

const float PI2 = 2.*abs(atan(0.,-1.));

// color
vec3 h2rgb( in float h )
{
    vec3 rgb = clamp( abs(mod(h*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
    return rgb*rgb*(3.0-2.0*rgb); // cubic smoothing
}

vec3 hsv2rgb( in float h, in float s, in float v)
{
    return v * mix( vec3(1.0), h2rgb(h), s);
}

// srgb <--> rgb (linear)
vec3 rgb2srgb( in vec3 col )
{
    return pow(col, vec3(1./2.2));
}
